interface:
Časy jsou řetězce "YYYY-MM-DDTHH:MM" bez časové zóny; počítej je přes Date.UTC (minuty od epochy), nikdy v lokálním čase. Výstupní časy ve stejném tvaru.
Import: import { pridejPracovniDny } from "./pracovnidny.mjs";  (pridejPracovniDny(datum "YYYY-MM-DD", n) -> "YYYY-MM-DD", vrátí n-tý pracovní den po datu, n = 0 vrátí datum)

export const STAVY = ["nova", "prirazena", "v-reseni", "ceka-na-dil", "hotova", "prevzata", "vyfakturovana", "zrusena"]
export const PRECHODY = { "nova": ["prirazena", "zrusena"], "prirazena": ["v-reseni", "nova", "zrusena"], "v-reseni": ["ceka-na-dil", "hotova"], "ceka-na-dil": ["v-reseni"], "hotova": ["prevzata", "v-reseni"], "prevzata": ["vyfakturovana"], "vyfakturovana": [], "zrusena": [] }
export const PRIORITY = {
  "havarie":   { "nazev": "Havárie",   "reakce": { "hodiny": 2 },        "vyreseni": { "hodiny": 24 } },
  "urgentni":  { "nazev": "Urgentní",  "reakce": { "hodiny": 24 },       "vyreseni": { "hodiny": 72 } },
  "bezna":     { "nazev": "Běžná",     "reakce": { "pracovniDny": 2 },   "vyreseni": { "pracovniDny": 10 } },
  "planovana": { "nazev": "Plánovaná", "reakce": { "pracovniDny": 10 },  "vyreseni": { "pracovniDny": 30 } }
}

Závada = { id, priorita, nahlaseno: čas, stav, dodavatel?, historie: [{ z, na, cas, kdo }] }.

export function pridejLhutu(cas, lhuta) -> čas
  { hodiny: h } -> cas + h hodin (přes půlnoc i měsíc správně). { pracovniDny: n } -> datum = pridejPracovniDny(datumová část, n), hodiny a minuty zůstanou.

export function terminy(zavada) -> { reakce, vyreseni }
  pridejLhutu(zavada.nahlaseno, PRIORITY[priorita].reakce / .vyreseni). Neznámá priorita -> throw new Error("priorita").

export function muzePrejit(z, na) -> boolean   (podle PRECHODY; neznámý stav -> false)

export function prejdi(zavada, na, cas, kdo) -> nová závada
  Když !muzePrejit(zavada.stav, na) -> throw new Error("neplatny-prechod"). Když na === "prirazena" a zavada.dodavatel chybí -> throw new Error("chybi-dodavatel").
  Vrať NOVÝ objekt { ...zavada, stav: na, historie: [...(zavada.historie || []), { z: zavada.stav, na, cas, kdo }] }. Vstup se nemutuje.

export function prirad(zavada, dodavatelId, cas, kdo) -> nová závada
  = prejdi({ ...zavada, dodavatel: dodavatelId }, "prirazena", cas, kdo)

export function casPrechodu(zavada, na) -> čas | null
  cas PRVNÍHO záznamu historie s daným `na`, jinak null.

export function slaStav(zavada, ted) -> { reakce, vyreseni }
  Stav "zrusena" -> { reakce: "zruseno", vyreseni: "zruseno" }.
  Jinak pro reakci (splnění = casPrechodu(zavada, "v-reseni"), termín = terminy(zavada).reakce) a pro vyřešení (splnění = casPrechodu(zavada, "hotova"), termín = terminy(zavada).vyreseni) zvlášť:
   - je-li čas splnění: "splneno" když splnění <= termín, jinak "poruseno";
   - jinak: "poruseno" když ted > termín; "ohrozeno" když minuty(ted) >= minuty(nahlaseno) + 0.75 * (minuty(termín) − minuty(nahlaseno)); jinak "bezi".

export function zbyva(zavada, ted) -> { reakce, vyreseni }
  Počet minut (celé číslo, může být záporné) od ted do příslušného termínu.

export function prehled(zavady, ted) -> { podleStavu, otevrene, poruseneSla }
  podleStavu: objekt se VŠEMI klíči ze STAVY (i nulovými) a počty. otevrene = počet závad ve stavech "nova", "prirazena", "v-reseni", "ceka-na-dil". poruseneSla = počet závad, u kterých je slaStav reakce NEBO vyreseni "poruseno".
